recs=[
R(6131476,"مسور کے سلوپی جوز","مسور کے یہ سلوپی جوز کلاسک ورژن کا پیٹ بھرنے والا اور تسلی بخش نباتاتی متبادل ہیں۔ پروٹین اور ذائقے سے بھرپور، یہ ایک مزیدار اور غذائیت بخش کھانا ہیں جسے بچے بھی پسند کرتے ہیں! اپنی ڈائبیٹیز پلیٹ مکمل کرنے کے لیے ساتھ میں ملا جلا سلاد شامل کریں۔","6","1 ہیمبرگر بن اور تقریباً ½ کپ مسور کا آمیزہ",
["1 درمیانی سفید پیاز (12 پتلے چھلوں میں کٹی ہوئی)","6 پتے لیٹوس","6 پورے گیہوں کے ہیمبرگر بن","1/4 چائے کا چمچ نمک","1/2 چائے کا چمچ اسموکڈ پاپریکا","1/2 چائے کا چمچ چلی پاؤڈر","1 کھانے کا چمچ ورسسٹرشائر ساس","1 کھانے کا چمچ براؤن شوگر","1/4 کپ ٹماٹر کی چٹنی","1 کپ مسور کی دال (ہری، دھلی ہوئی)","2 کپ کم سوڈیم والا سبزی کا شوربہ","2 جوے لہسن (باریک کٹے ہوئے)","1 چھوٹی پیلی پیاز (کٹی ہوئی)","1 کھانے کا چمچ ایکسٹرا ورجن زیتون کا تیل"],
["ساس پین کو درمیانی آنچ پر رکھیں۔ تیل، پیاز اور لہسن ڈالیں۔ وقفے وقفے سے ہلاتے ہوئے پکائیں، جب تک پیاز نرم ہونا شروع نہ ہو، 3–4 منٹ۔","شوربہ اور مسور ڈالیں۔ ابال آنے دیں، پھر آنچ دھیمی کر کے ڈھانپ دیں اور تقریباً 20 منٹ پکائیں، جب تک مسور نرم نہ ہو جائے۔","ٹماٹر کی چٹنی، براؤن شوگر، ورسسٹرشائر ساس اور مسالے ڈال کر ہلائیں۔","پیش کرنے کے لیے مسور کو بنز میں تقسیم کریں۔ اوپر لیٹوس اور پیاز کے چھلے رکھیں۔","ساتھ میں ملا جلا سلاد پیش کریں۔"]),
R(6131494,"لیموں اور اجمودے کی ٹاپنگ والے مچھلی کے فلے","یہ رہا ہفتے کے دنوں کا ایک جلدی تیار ہونے والا رات کا کھانا جو آپ اپنے خاندان کے ساتھ کھا سکتے ہیں۔ جب وقت کم ہو تو مچھلی ایک بہترین مین ڈش بن سکتی ہے کیونکہ یہ جلدی پک جاتی ہے، اور اس کے علاوہ یہ کم چکنائی والے پروٹین کا بہترین ذریعہ ہے۔","4","4 ½ اونس پکی ہوئی مچھلی + 1 کھانے کا چمچ اجمودے کا آمیزہ",
["4 پورے کم چکنائی والی سفید مچھلی کے فلے (ہر ایک 6 اونس، جیسے تلاپیا، اسنیپر، یا فلاؤنڈر، دھوئے ہوئے اور خشک کیے ہوئے)","1/8 چائے کا چمچ پاپریکا (حسب ذائقہ)","2 کھانے کے چمچ ایکسٹرا ورجن زیتون کا تیل","1/2 چائے کا چمچ لیموں کا چھلکا","1 کھانے کا چمچ اجمودا (باریک کٹا ہوا)","1/8 چائے کا چمچ خشک سویا (خشک)","1 درمیانا لیموں (آدھا کٹا ہوا)"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔","بیکنگ ٹرے پر ورق بچھائیں، ورق پر کوکنگ اسپرے لگائیں، فلے کو ورق پر ترتیب دیں اور برابر پاپریکا چھڑکیں۔ اگر چاہیں تو ہلکا سا نمک اور کالی مرچ ڈالیں۔ 10 منٹ بیک کریں یا جب تک مچھلی بیچ میں سے مبہم سفید نہ ہو جائے۔","جب مچھلی پک رہی ہو، لیموں کے آدھے ٹکڑوں کے علاوہ باقی اجزاء کو ایک چھوٹے پیالے میں ملا کر ایک طرف رکھ دیں۔","سوراخ دار اسپیچولا سے مچھلی کو نکالیں، چار ڈنر پلیٹوں پر رکھیں اور سب پر برابر لیموں کا رس نچوڑیں۔ اوپر اجمودے کا آمیزہ ڈالیں۔"]),
R(6131682,"آم اور ٹماٹر کی سالسا","تازہ پیداوار سے بنی یہ گھر کی بنی سالسا دکان سے ملنے والی ڈبہ بند سالسا سے زیادہ غذائیت بخش اور کم سوڈیم والی ہے۔ اسے ٹاکوز، کیساڈیلاز یا گرل کیے ہوئے چکن کے اوپر پیش کریں!","5","1/2 کپ",
["1 چھوٹی ہلاپینو مرچ (کٹی ہوئی)","1 کپ ٹماٹر (کٹے ہوئے)","1 کپ آم (کٹا ہوا)","1/4 کپ سفید پیاز (کٹی ہوئی)","1/2 کپ ہرا دھنیا (کٹا ہوا)","1 چائے کا چمچ زیتون کا تیل","1 چائے کا چمچ لائم کا رس"],
["طے کریں کہ آپ کتنی ہلاپینو استعمال کرنا چاہتے ہیں۔ اگر بیج نکالنا پسند کریں تو احتیاط سے نکالیں۔ آنکھوں اور ناک کو چھونے سے بچیں۔","تمام اجزاء کو ملائیں۔","گرم مکئی کی ٹورٹیلا یا گرل کیے ہوئے گوشت کے ساتھ پیش کریں۔"]),
R(6132615,"ایوکاڈو ٹماٹر ٹوسٹ","یہ تازہ اور تسلی بخش ٹوسٹ کرارے سالم اناج کی ڈبل روٹی پر ملائم ایوکاڈو اور رسیلے ٹماٹر کی تہیں لگاتا ہے۔ یہ جلدی بنتا ہے، ذائقے سے بھرپور ہے اور اسنیک کے لیے بہترین ہے۔","1","1 سلائس",
["1 سلائس سالم اناج کا ٹوسٹ","1/2 پورا ایوکاڈو","1/2 پورا ٹماٹر (کٹا ہوا)"],
["سالم اناج کی ڈبل روٹی کے ایک سلائس کو اتنا ٹوسٹ کریں جتنا آپ کو کرارا پسند ہو۔","ایوکاڈو کے 1/2 حصے کو کانٹے سے ہلکا سا میش کریں اور ٹوسٹ پر پھیلا دیں۔","کٹا ہوا 1/2 ٹماٹر اوپر رکھیں۔","فوراً پیش کریں۔"]),
R(6135376,"روزمیری میں بھنا ہوا کورنش گیم ہین","کورنش گیم ہینز چھوٹے سائز کے مرغ کی ایک قسم ہیں اور تہوار کا منفرد کھانا بن سکتی ہیں۔ اگر آپ کو کریانے کی دکان میں کورنش گیم ہینز نہ ملیں تو یہی ترکیب ہڈی والی چکن بریسٹ کے ساتھ بنائی جا سکتی ہے۔","4","½ گیم ہین",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1 کھانے کا چمچ تازہ روزمیری (باریک کٹی ہوئی)","1/4 چائے کا چمچ کالی مرچ","1/2 چائے کا چمچ نمک (اختیاری)","2 جوے لہسن (باریک کٹے ہوئے یا کدوکش کیے ہوئے)","1 کھانے کا چمچ ڈیجون رائی","2 کھانے کے چمچ لیموں کا رس (1 درمیانے لیموں سے تازہ نچوڑا ہوا)","1 چائے کا چمچ لیموں کا چھلکا (1 درمیانے لیموں سے)","1 کھانے کا چمچ زیتون کا تیل","2 پورے کورنش گیم ہینز (ہر ایک تقریباً 1 1/4 پاؤنڈ)","4 ٹہنیاں تازہ روزمیری"],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔ ایک بڑی شیشے یا دھات کی بیکنگ ڈش پر کوکنگ اسپرے لگائیں۔","ایک چھوٹے پیالے میں زیتون کا تیل، لیموں کا چھلکا، لیموں کا رس، ڈیجون رائی، لہسن، نمک (اختیاری)، کالی مرچ اور باریک کٹی ہوئی روزمیری پھینٹ کر ملائیں۔","ہر گیم ہین کو لمبائی میں آدھا کاٹیں اور کھال اتار دیں۔ کاغذی تولیے سے خشک کریں۔ بیکنگ ڈش کے پیندے میں روزمیری کی 4 ٹہنیاں بچھا دیں۔","ہینز کو بیکنگ ڈش میں سینے والا حصہ اوپر کر کے رکھیں (ہر روزمیری کی ٹہنی کے اوپر ایک آدھا حصہ)۔ ہر ہین پر فراخ دلی سے میرینیڈ برش کریں (سارا میرینیڈ استعمال کریں)۔","30–35 منٹ بیک کریں یا جب تک اندرونی درجہ حرارت 165 ڈگری F تک نہ پہنچ جائے۔"]),
R(6135574,"ناشتے میں پزا کے شوقین","یہ انتہائی آسان ناشتہ آزمائیں۔ اسے بچے اور بڑے دونوں پسند کریں گے اور یہ چند ہی منٹوں میں کھانے کے لیے تیار ہو سکتا ہے! اگر آپ کے بجٹ کے لیے زیادہ مناسب ہو تو بادام کے مکھن کی جگہ مونگ پھلی کا مکھن استعمال کریں۔","2","½ انگلش مفن",
["1 پورا سالم گیہوں کا انگلش مفن","2 کھانے کے چمچ بادام کا مکھن","1/2 کپ اسٹرابیریز (کٹی ہوئی)","1 1/2 چائے کے چمچ بغیر میٹھے کے ناریل کے فلیکس (کدوکش کیے ہوئے)"],
["انگلش مفن کو چیر کر ٹوسٹ کریں۔","ہر آدھے حصے پر بادام کا مکھن لگائیں۔","اوپر کٹی ہوئی اسٹرابیریز رکھیں۔","ناریل چھڑکیں۔"]),
R(6137042,"کرین بیری اور ہیزل نٹس والی ہری پھلیاں","ہری پھلیوں کی سائیڈ ڈش کو کھٹی کرین بیری، تازہ لیموں کے چھلکے اور کرارے ہیزل نٹس سے نکھاریں! یہ سادہ سائیڈ ڈش عمدہ لگتی ہے لیکن بنانا بہت آسان ہے۔ یہ آپ کی تھینکس گیونگ کی میز کے لیے ایک اچھا، ہلکا اضافہ بھی ہے۔","16","1/2 کپ",
["2 پاؤنڈ تازہ ہری پھلیاں (سرے کٹے ہوئے)","1 کھانے کا چمچ زیتون کا تیل","3 کھانے کے چمچ خشک کرین بیری","1/4 کپ ہیزل نٹس (موٹے کٹے ہوئے)","1/4 چائے کا چمچ کالی مرچ","1/4 چائے کا چمچ نمک","2 چائے کے چمچ لیموں کا چھلکا"],
["ایک بڑے برتن کو 2/3 پانی سے بھریں اور ابالیں۔ ہری پھلیاں ڈالیں، آنچ بند کر دیں اور پھلیوں کو 3 منٹ پانی میں پڑا رہنے دیں۔ پھلیاں چھان کر پیش کرنے والے پیالے یا تھالی میں ڈال دیں۔","ایک چھوٹے پیالے میں تیل، میوے، کرین بیری، نمک اور کالی مرچ ملائیں۔ ہری پھلیوں پر کرین بیری اور میوے کا آمیزہ ڈالیں۔ لیموں کے چھلکے سے سجائیں۔"]),
R(6137953,"نمک سے پاک کیجن مسالہ","دکان سے خریدے ہوئے کیجن مسالے میں فی چائے کا چمچ 1000 ملی گرام سے زیادہ نمک ہو سکتا ہے! یہ نمک سے پاک آمیزہ وہی کیجن ذائقے فراہم کرتا ہے، لیکن آپ خود طے کر سکتے ہیں کہ تیار ڈش میں کتنا نمک جائے۔ آپ اس مسالے کو چکن، مچھلی یا دوسری سمندری غذا پر، بھاپ میں پکی یا بھنی ہوئی سبزیوں پر چھڑک کر، یا پاپ کارن کے مسالے کے طور پر استعمال کر سکتے ہیں۔ امکانات لامحدود ہیں!","20","1 چائے کا چمچ",
["2 کھانے کے چمچ پاپریکا","1 کھانے کا چمچ لہسن پاؤڈر","1 کھانے کا چمچ پیاز پاؤڈر","2 چائے کے چمچ کالی مرچ","2 چائے کے چمچ کیین مرچ","2 چائے کے چمچ خشک تھائم","2 چائے کے چمچ خشک اوریگانو"],
["تمام اجزاء کو ایک ساتھ ملائیں۔ ہوا بند ڈبے میں محفوظ رکھیں۔"]),
R(6139190,"کھلا چنے کے سلاد والا سینڈوچ","اس کھلے چنے کے سلاد والے سینڈوچ کے تازہ اور تسلی بخش ذائقوں کا لطف اٹھائیں، جو ویگن میل پیٹرن کا ایک مزیدار انتخاب ہے۔ چنے، کرارے سبزیوں اور تیز ذائقے والی ڈریسنگ کا آمیزہ ٹوسٹ کی ہوئی ڈبل روٹی کے سلائس پر ڈھیر کیا جاتا ہے، جو ایک رنگین اور غذائیت بخش کھانا بناتا ہے جو ہلکا بھی ہے اور پیٹ بھرنے والا بھی۔ جلدی لنچ یا ہلکے ڈنر کے لیے بہترین۔","4","1 سلائس ڈبل روٹی، ⅔ کپ چنے کی بھرائی",
["30 اونس ڈبہ بند چنے (بغیر اضافی نمک)","1 کھانے کا چمچ تازہ سویا (کٹا ہوا)","1/3 کپ کم چکنائی والی ویگن مایونیز","2 چائے کے چمچ ڈیجون رائی","2 چائے کے چمچ ایپل سائیڈر سرکہ","1/4 چائے کا چمچ پیاز پاؤڈر","1/4 چائے کا چمچ پاپریکا","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","4 سلائس سالم اناج کی ڈبل روٹی","1/2 پیکٹ (5 اونس) اسپرنگ مکس سلاد","1 پورا ٹماٹر (کٹا ہوا)","1 کھانے کا چمچ فلیٹ لیف اجمودا (کٹا ہوا)","2 بڑی گاجریں (چھلی ہوئی اور 2 انچ کی لمبی قاشوں میں کٹی ہوئی)","2 ڈنڈیاں اجوائن (صاف کی ہوئی اور 2 انچ کی لمبی قاشوں میں کٹی ہوئی)"],
["چنے چھان کر دھو لیں۔ ایک درمیانے پیالے میں منتقل کریں۔","پیالے میں تازہ سویا، مایونیز، ڈیجون، سرکہ اور مسالے ڈالیں۔","کانٹے یا آلو میشر سے چنوں کو کچل لیں تاکہ نیم ہموار آمیزہ بن جائے۔","ڈبل روٹی کے سلائس ٹوسٹ کریں۔ پلیٹوں میں تقسیم کریں اور اوپر اسپرنگ مکس، ٹماٹر کے قتلے اور چنے کا آمیزہ رکھیں۔ ساتھ میں سبزیوں کی قاشیں پیش کریں۔"]),
R(6139340,"زوکینی نوڈلز کے ساتھ بینگن کے میٹ بالز","یہ ایک سبزی خور ترکیب ہے جس میں بینگن کے میٹ بالز ہیں جو کلاسک ڈش کا نباتاتی انداز پیش کرتے ہیں اور ہلکے اور نرم زوکینی نوڈلز پر پیش کیے جاتے ہیں، تاکہ ایک آرام دہ مگر کم کاربوہائیڈریٹ والا کھانا بنے۔ بادام کا آٹا اور پارمیزان میٹ بالز کو ساخت اور ذائقہ دیتے ہیں، جبکہ سبزیوں کا فائبر ہاضمے کو سست کرنے میں مدد دیتا ہے۔ پروٹین، فائبر اور صحت مند چکنائیوں کے امتزاج کے ساتھ، یہ خون میں گلوکوز (بلڈ شوگر) کی سطح کو مستحکم رکھنے کے لیے ایک بہترین انتخاب ہے۔","4","تقریباً 3–4 میٹ بالز + 1 کپ زوکینی نوڈلز",
["1 درمیانا بینگن (چھلا ہوا اور چوکور کٹا ہوا)","2 چائے کے چمچ ایکسٹرا ورجن زیتون کا تیل","1/2 چھوٹی لال پیاز (باریک کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","1/3 کپ بادام کا آٹا","1/4 پارمیزان پنیر (کدوکش کیا ہوا)","1/4 کپ تازہ اجمودا (کٹا ہوا)","1 چائے کا چمچ خشک اوریگانو","1/4 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس","1/4 چائے کا چمچ کالی مرچ","1 پورا انڈا (ہلکا پھینٹا ہوا)","4 درمیانی زوکینی (اسپائرلائز کی ہوئی)","1/8 چائے کا چمچ ایک چٹکی نمک","1 کپ مرینارا ساس (بغیر اضافی چینی)","1/4 کپ تازہ تلسی (کٹی ہوئی)"],
["اوون کو 375 ڈگری F پر پہلے سے گرم کریں۔","کٹے ہوئے بینگن کو نرم ہونے تک بھاپ دیں یا مائیکرو ویو کریں (تقریباً 8–10 منٹ)۔ ذرا ٹھنڈا ہونے دیں، پھر صاف کچن تولیے یا چیز کلاتھ میں منتقل کر کے اضافی نمی نچوڑ دیں۔","ایک اسکلیٹ میں درمیانی آنچ پر 1 چائے کا چمچ زیتون کا تیل گرم کریں۔ پیاز اور لہسن ڈال کر 3–4 منٹ پکائیں، جب تک نرم نہ ہو جائیں۔","ایک مکسنگ باؤل میں پکے ہوئے بینگن کو کانٹے یا آلو میشر سے میش کریں۔ بھونی ہوئی پیاز اور لہسن، بادام کا آٹا، پارمیزان، اجمودا، اوریگانو، کٹی ہوئی لال مرچ، کالی مرچ اور انڈا ڈالیں۔ اچھی طرح ملنے تک مکس کریں۔","بیکنگ ٹرے پر پارچمنٹ پیپر بچھا دیں۔ آمیزے سے 12–16 چھوٹے گولے بنا کر ٹرے پر رکھیں۔ 25–30 منٹ بیک کریں، آدھے وقت پر پلٹ دیں، جب تک سخت اور سنہری نہ ہو جائیں۔","ایک بڑے نان اسٹک اسکلیٹ میں تیز درمیانی آنچ پر 1 چائے کا چمچ زیتون کا تیل گرم کریں۔ زوکینی نوڈلز اور ایک چٹکی نمک ڈالیں۔ 2–3 منٹ بھونیں جب تک بس نرم نہ ہو جائیں۔ ضرورت ہو تو اضافی نمی نکال دیں۔","مرینارا ساس کو چھوٹے ساس پین یا مائیکرو ویو میں گرم ہونے تک گرم کریں۔","زوکینی نوڈلز کو 4 پلیٹوں میں تقسیم کریں۔ اوپر بینگن کے میٹ بالز رکھیں اور اوپر گرم مرینارا چمچ سے ڈالیں۔ تلسی سے سجائیں۔"]),
R(6139937,"ٹرکی چلی سے بھرے میٹھے آلو","تازہ چلی اور بیک کیے ہوئے میٹھے آلو ایک بہترین امتزاج ہیں! اس ترکیب کو آپ اپنے ذائقے کے مطابق آسانی سے بدل سکتے ہیں۔ تیزی ایک یا دو درجے بڑھانے کے لیے ایک چٹکی کیین یا مرچ ڈالیں۔ اپنے میٹھے آلو پر ہری پیاز یا (کھٹی کریم کی جگہ) سادہ بغیر چکنائی کے یونانی دہی کا ایک چمچ ڈال کر آزمائیں۔ اس ترکیب کو اپنے انداز سے بنانے کے امکانات لامحدود ہیں!","4","فی سرونگ 1 میٹھا آلو اور 1 کپ چلی",
["4 چھوٹے میٹھے آلو","2 کھانے کے چمچ زیتون کا تیل (تقسیم شدہ)","2 جوے لہسن (باریک کٹے ہوئے)","1/4 کپ گاجر (کدوکش کی ہوئی)","2 ڈنڈیاں اجوائن (چھوٹی کٹی ہوئی)","1 چھوٹی پیلی پیاز (چھوٹی کٹی ہوئی)","1 چھوٹی لال شملہ مرچ (کٹی ہوئی)","1 چائے کا چمچ چلی پاؤڈر","1/2 چائے کا چمچ پیاز پاؤڈر","1/2 چائے کا چمچ خشک اوریگانو","1/2 کپ مسور کی دال","8 اونس کم سوڈیم یا بغیر اضافی نمک کی ٹماٹر کی چٹنی (1 ڈبہ)","3 کپ کم سوڈیم والا چکن شوربہ","1/2 پاؤنڈ ٹرکی کا قیمہ","1/3 کپ کم چکنائی والا کدوکش کیا ہوا چیڈر"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔ آلوؤں کے چھلکوں میں کانٹے سے سوراخ کریں اور بیکنگ ٹرے پر رکھیں۔ 60 منٹ بیک کریں یا جب تک پوری طرح اندر سے نرم نہ ہو جائیں۔","ایک بڑے برتن کو درمیانی آنچ پر گرم کریں۔ لہسن، گاجر، اجوائن، پیاز، شملہ مرچ، مسالے اور 1 کھانے کا چمچ زیتون کا تیل ڈالیں۔ وقفے وقفے سے ہلاتے ہوئے پکائیں جب تک نرم نہ ہو جائیں، 4–5 منٹ۔","مسور، ٹماٹر کی چٹنی اور شوربہ ڈالیں۔ ابال آنے دیں پھر آنچ ہلکی کر کے 30 منٹ دھیمی آنچ پر پکائیں جب تک مسور نرم نہ ہو جائے۔","جب چلی تقریباً تیار ہو جائے تو اسکلیٹ کو درمیانی آنچ پر گرم کریں۔ باقی زیتون کا تیل اور ٹرکی ڈالیں۔ چمچ سے توڑتے ہوئے پکائیں جب تک ریزہ ریزہ اور بھورا نہ ہو جائے۔ آخری 10 منٹ کے لیے سوپ میں ڈال دیں۔","ہر میٹھے آلو کو احتیاط سے چیر کر اس کا اندرونی حصہ میش کریں۔ ہر آلو پر 1 کپ چلی چمچ سے ڈالیں، پھر اوپر 2 کھانے کے چمچ پنیر ڈالیں۔"]),
R(6140067,"کیلیفورنیا کھجور اور پالک کے ساتھ مسور کا سوپ","یہ پیٹ بھرنے والا سوپ مراکشی آرام دہ ذائقوں سے متاثر ہے، جو ہر چمچ میں گرمی اور غذائیت پہنچاتا ہے۔ دھواں دار مسور اور تازہ پالک ایک تسلی بخش بنیاد بناتے ہیں، جبکہ قدرتی طور پر میٹھی کیلیفورنیا کھجوریں ایک ہلکا اور متوازن ذائقہ شامل کرتی ہیں۔ یہ کم چکنائی والا سبزی خور سوپ فائبر کا بہترین ذریعہ ہے۔ زیادہ کریمی ساخت کے لیے پیش کرنے سے پہلے سوپ کا کچھ حصہ بلینڈ کر سکتے ہیں۔","6","1 کپ",
["1 کھانے کا چمچ زیتون کا تیل","3/4 کپ پیلی پیاز (کٹی ہوئی)","1/2 کپ گاجر (کٹی ہوئی)","1/2 کپ اجوائن (کٹی ہوئی)","3 جوے لہسن (باریک کٹے ہوئے)","2 چائے کے چمچ پسا ہوا زیرہ","2 چائے کے چمچ پسا ہوا دھنیا","1 چائے کا چمچ اسموکڈ پاپریکا","3/4 کپ خشک مسور کی دال (دھلی ہوئی)","1 ڈبہ (14.5 اونس) بغیر اضافی نمک کے کٹے ہوئے ٹماٹر","4 کپ بغیر نمک کا سبزی کا شوربہ","2 کپ پانی","1 چائے کا چمچ نمک","1/2 چائے کا چمچ کالی مرچ","2 کپ تازہ بے بی پالک","2 پوری کیلیفورنیا کھجوریں (گٹھلی نکالی ہوئی، باریک کٹی ہوئی)","1 کھانے کا چمچ لیموں کا رس"],
["ایک بڑے برتن میں درمیانی آنچ پر زیتون کا تیل گرم کریں۔ پیاز، گاجر اور اجوائن ڈالیں۔ 3–4 منٹ بھونیں جب تک نرم ہونا شروع نہ ہو جائیں۔","لہسن، زیرہ، دھنیا اور پاپریکا ڈالیں۔ مزید 30 سیکنڈ پکائیں جب تک خوشبو نہ آنے لگے۔","مسور، ٹماٹر، سبزی کا شوربہ اور پانی ڈال کر ہلائیں۔ ابال آنے دیں، پھر آنچ کم کریں اور ڈھکن ذرا کھلا رکھ کر 25–30 منٹ دھیمی آنچ پر پکائیں، جب تک مسور نرم نہ ہو جائے۔ نمک اور کالی مرچ ڈال کر ہلائیں۔","پالک اور کھجوریں ڈال کر ہلائیں۔ 2–3 منٹ پکائیں جب تک پالک مرجھا نہ جائے۔","تازہ لیموں کا رس ڈال کر ہلائیں۔ سوپ گرم پیش کریں۔"]),
R(6140897,"پیکن کی تہہ والی چکن بریسٹ","اس چکن ڈش میں تیاری کا صرف 8 منٹ، اوون میں 20 منٹ لگتے ہیں، اور بس! نتیجہ اتنا شاندار ہے کہ کسی خاص موقع پر پیش کیا جا سکتا ہے لیکن اتنا آرام دہ کہ آپ کے آرام دہ لباس کے ساتھ بھی جچے۔ آپ پیکن کے گھریلو کرارے پن کے ساتھ قدرتی مٹھاس اور تیزی کے ہلکے سے احساس کا لطف اٹھائیں گے۔ اسے ہارویسٹ سلاد اور میٹھے آلو کے فرائز کے ساتھ پیش کریں۔","4","1 بریسٹ (تقریباً 5 اونس)",
["1/2 کپ پیکن کے ٹکڑے","4 (6 اونس کی) بغیر ہڈی اور بغیر چھلکے کی چکن بریسٹ","3 کھانے کے چمچ بغیر میٹھے کی سیب کی چٹنی","1 کھانے کا چمچ تیز بھوری رائی","1/4 چائے کا چمچ سمندری نمک"],
["اوون کو 425° F پر پہلے سے گرم کریں۔ ایک بڑی کنارے دار بیکنگ ٹرے تیار کریں۔ آسان صفائی اور کم چپکنے کے لیے اس پر پارچمنٹ پیپر بچھائیں (اختیاری)۔","پیکن کو فوڈ پروسیسر میں ڈالیں۔ بار بار تھوڑا تھوڑا چلائیں جب تک وہ ڈبل روٹی کے چورے جیسے نہ لگیں۔ ایک کنارے دار پلیٹ میں منتقل کریں۔","چکن کو بیکنگ ٹرے پر رکھیں۔ ایک چھوٹے پیالے میں سیب کی چٹنی اور رائی کو ملا کر ہلائیں۔ سیب کی چٹنی اور رائی کا آمیزہ ہر بریسٹ کے اوپر چمچ سے ڈالیں اور چمچ کی پشت سے برابر پھیلا دیں۔","ہر چکن بریسٹ کا سیب کی چٹنی اور رائی والا رخ پیکن میں مضبوطی سے دبائیں۔ چکن کو دوبارہ بیکنگ ٹرے پر پیکن والا رخ اوپر کر کے رکھیں۔","باقی بچے ہوئے پیکن چکن پر چھڑکیں؛ چپکانے کے لیے دبائیں۔ اوپر نمک چھڑکیں۔","تقریباً 20 منٹ بیک کریں، یا جب تک چکن کا اندرونی درجہ حرارت 165° F تک نہ پہنچ جائے۔ چار ڈنر پلیٹوں میں تقسیم کریں اور پیش کریں۔"]),
R(6142192,"گرل کیا ہوا آم چکن","اپنے اگلے باربی کیو یا پکنک میں یہ صحت بخش گرل کیے ہوئے چکن کی ترکیب پیش کریں۔ یہ تلے ہوئے چکن یا برات وورسٹ کا بہترین متبادل ہے۔ آپ کے مہمان ایک زیادہ صحت مند انتخاب کو سراہیں گے اور اس ہلکی میٹھی اور کھٹی ڈش سے لطف اندوز ہوں گے۔","4","1 چکن بریسٹ (117 گرام)",
["1 پاؤنڈ چکن بریسٹ کٹلیٹس (4 بغیر ہڈی کے، (کل 1 پاؤنڈ)، بغیر چھلکے کے)","2 کھانے کے چمچ آم کی چٹنی یا آم کی سالسا","2 کھانے کے چمچ تازہ لائم کا رس","2 چائے کے چمچ کدوکش کیا ہوا تازہ ادرک، یا 1/2 چائے کا چمچ پسا ہوا ادرک","1 کھانے کا چمچ زیتون کا تیل","1/4 کپ مالٹے کا رس","1 چائے کا چمچ باریک کٹا ہوا تازہ اوریگانو یا 1/4 سے 1/2 چائے کا چمچ خشک اوریگانو","1/2 چائے کا چمچ تیز مرچ کی ساس","2 جوے لہسن (باریک کٹے ہوئے)"],
["ایک بڑی دوبارہ بند ہونے والی پلاسٹک اسٹوریج تھیلی میں چکن کو باقی اجزاء کے ساتھ ملائیں۔ فریج میں رکھیں اور 8 گھنٹے یا رات بھر میرینیٹ کریں، میرینیٹ کرنے کے دوران آدھے وقت پر پلٹ دیں۔","گرل کو تیز درمیانی آنچ پر پہلے سے گرم کریں۔ چکن کو گرل پر رکھیں، بچا ہوا میرینیڈ پھینک دیں۔ چکن کو ہر طرف 4 سے 6 منٹ گرل کریں، یا جب تک اچھی طرح پک نہ جائے۔"]),
R(6142330,"کرارے بیج اور بادام کا ٹریل مکس","یہ کرارے بیج اور بادام کا ٹریل مکس مضبوط بادام کو کدو اور سورج مکھی کے بیجوں کے ساتھ ملا کر ایک سادہ، غذائیت سے بھرپور اسنیک بناتا ہے۔ یہ تسلی بخش ہے، حصوں میں بانٹنا آسان ہے، اور گھر پر یا چلتے پھرتے توانائی کی فوری خوراک کے لیے بہترین ہے۔","1","4 کھانے کے چمچ",
["2 کھانے کے چمچ بادام","1 کھانے کا چمچ کدو کے بیج","1 کھانے کا چمچ سورج مکھی کے بیج"],
["2 کھانے کے چمچ بادام، 1 کھانے کا چمچ کدو کے بیج اور 1 کھانے کا چمچ سورج مکھی کے بیج ایک چھوٹے پیالے یا ڈبے میں ڈالیں۔","آہستہ سے ملانے کے لیے اچھالیں۔","فوراً کھائیں یا بعد کے لیے ہوا بند ڈبے میں محفوظ رکھیں۔"]),
]
save(3,recs)
